   if(crop){var bm=new FormatConvertedBitmap(source,PixelFormats.Bgra32,null,0);int w=bm.PixelWidth,h=bm.PixelHeight;byte[] p=new byte[w*h*4];bm.CopyPixels(p,w*4,0);int x0=w,x1=0,y0=h,y1=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++)if(p[(y*w+x)*4+3]>20){x0=Math.Min(x0,x);x1=Math.Max(x1,x);y0=Math.Min(y0,y);y1=Math.Max(y1,y);}if(x1>x0)source=new CroppedBitmap(source,new Int32Rect(x0,y0,x1-x0+1,y1-y0+1));}source.Freeze();cache[key]=source;return source;}
