  void Graph(Canvas c,double x,double y,double w,double h,bool edit){var p=Pane(c,x,y,w,h,tileBg,0);p.Background=Brushes.Transparent;for(int i=0;i<=8;i++){Put(p,new Rectangle{Fill=B(line)},i*w/8,0,1,h);if(edit)Label(c,(20+i*10).ToString(),x+i*w/8-12,y+h+3,38,18,10,muted);}for(int i=0;i<=5;i++){Put(p,new Rectangle{Fill=B(line)},0,i*h/5,w,1);if(edit)Label(c,(100-i*20)+"%",x+w+8,y+i*h/5-8,38,18,10,muted);}if(!edit){Label(p,"选择预设以查看真实曲线或创建本地曲线",12,12,w-24,24,12,muted);return;}Label(c,"°C",x+w+6,y+h,30,18,10,muted);var curve=CurrentCurve();var points=new PointCollection();for(int i=0;i<curve.Values.Count;i++)points.Add(new Point((curve.Temperatures[i]-20)*w/80,h*(1-curve.Values[i]/100)));Func<PointCollection> fullCurve=()=>{var full=new PointCollection(points);full.Insert(0,new Point(0,points[0].Y));full.Add(new Point(w,points[points.Count-1].Y));return full;};var stroke=new Polyline{Points=fullCurve(),Stroke=B("#DDD600"),StrokeThickness=2,IsHitTestVisible=false};Put(p,stroke,0,0,w,h);var info=Label(c,"",x+200,y-22,400,20,11,muted);var marker=new Line{Y1=0,Y2=h,Stroke=B("#B7A600"),StrokeThickness=1,IsHitTestVisible=false};Put(p,marker,0,0,w,h);Action mark=()=>{var r=Telemetry.Named(curve.Sensor=="CPU 温度"?"CPU 温度":"冷却液温度");marker.Visibility=r.Value.HasValue?Visibility.Visible:Visibility.Collapsed;if(r.Value.HasValue)marker.X1=marker.X2=Math.Max(0,Math.Min(w,(r.Value.Value-20)*w/80));};mark();live.Add(mark);for(int i=0;i<points.Count;i++){int k=i;var dot=new Border{Width=20,Height=20,Background=Brushes.Transparent,Cursor=Cursors.SizeAll,Child=new Ellipse{Width=10,Height=10,Fill=B("#DDD600")}};Put(p,dot,points[i].X-10,points[i].Y-10);dot.ToolTip=curve.Temperatures[k]+" °C / "+curve.Values[k]+" %";dot.MouseLeftButtonDown+=(sender,e)=>{dot.CaptureMouse();e.Handled=true;};dot.MouseMove+=(sender,e)=>{if(!dot.IsMouseCaptured)return;var pos=e.GetPosition(p);double low=k==0?20:curve.Temperatures[k-1]+1,high=k==points.Count-1?100:curve.Temperatures[k+1]-1;curve.Temperatures[k]=Math.Max(low,Math.Min(high,Math.Round(20+pos.X/w*80)));curve.Values[k]=Math.Max(0,Math.Min(100,Math.Round((1-pos.Y/h)*100)));points[k]=new Point((curve.Temperatures[k]-20)*w/80,h*(1-curve.Values[k]/100));stroke.Points=fullCurve();Canvas.SetLeft(dot,points[k].X-10);Canvas.SetTop(dot,points[k].Y-10);info.Text=curve.Temperatures[k]+" °C  /  "+curve.Values[k]+" %";dot.ToolTip=info.Text;curve.Edited=true;coolingApplyStatus="曲线已改动，尚未应用";};dot.MouseLeftButtonUp+=(sender,e)=>{if(dot.IsMouseCaptured){dot.ReleaseMouseCapture();Save();e.Handled=true;}};dot.LostMouseCapture+=(sender,e)=>{if(curve.Edited){Save();QueueBoundCooling(curve);}};}}

