  public void Verify(string dir){Directory.CreateDirectory(dir);Pref=new Preferences{Theme="深色",Profiles=new List<Profile>{new Profile()},Sensors=new List<string>(SensorNames)};P.Cooler.Layers.Add(new LightLayer());P.Cooler.FanLayers.Add(new LightLayer{Effect="彩虹波浪"});P.Memory.Layers.Add(new LightLayer());var log=new List<string>();Action<string> capture=name=>{UpdateLayout();var r=new RenderTargetBitmap(1390,840,96,96,PixelFormats.Pbgra32);r.Render(surface);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(r));using(var f=File.Create(System.IO.Path.Combine(dir,name+".png")))png.Save(f);log.Add(name+": render OK");};foreach(var theme in new[]{"深色","亮色"}){Pref.Theme=theme;foreach(var pg in new[]{"主页","控制面板","Murals"}){page=pg;Build();capture(theme+"-"+pg);}page="设备";device="H100i ELITE LCD";foreach(var t in new[]{"灯光效果设置","环","8-LED风扇系列","屏幕设置","散热","警告"}){tab=t;editing=t=="环"||t=="警告";activeLayer=0;Build();capture(theme+"-"+t);}device="DOMINATOR PLATINUM RGB DDR5";tab="Dimm 设置";Build();capture(theme+"-DIMM");page="主页";Build();foreach(var st in new[]{"一般设置","控制面板","软件更新","插件","传感器记录","SDK","集成","小组件访问权限","隐私","设备设置"}){SettingsModal(st);capture(theme+"-设置-"+st);}}
   foreach(var theme in new[]{"深色","亮色"}){Pref.Theme=theme;page="设备";device="H100i ELITE LCD";tab="灯光效果设置";Build();SetupWizard();capture(theme+"-4针向导");CloseModal();} VerifyAdvanced(log,capture);P.Name="持久化测试";P.Cooler.Brightness=43;Save();var saved=Read(Store);if(saved.Profiles.Count!=1||saved.Profiles[0].Name!="持久化测试"||saved.Profiles[0].Cooler.Brightness!=43)throw new Exception("配置恢复失败");log.Add("Profile and device state round trip: OK");var clone=CloneProfile(P);if(clone.Cooler.Brightness!=P.Cooler.Brightness||Object.ReferenceEquals(clone.Cooler,P.Cooler))throw new Exception("深复制验证失败");log.Add("Profile deep copy: OK");SetOption("customMural:测试场景","纯色");if(!AllScenes().Contains("测试场景"))throw new Exception("自定义场景创建失败");log.Add("Custom scene creation: OK");VerifyDesktopFeatures(log);File.WriteAllLines(System.IO.Path.Combine(dir,"verification.txt"),log);Close();}
